"use client";
/* Mochi, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Mochi(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("mochi"); }, []);
  return React.createElement("piix-sprite", { "name": "mochi", ...piixAttrs(props) });
}

export default Mochi;
